/**
 * 势力存续年表（factionId → 起止年）。
 *
 * 🔴 2026-11-04 主人令「势力的时代看大部分年在哪个时间段」：本表是「多数年段」判定的唯一数据源，
 *   只用于审计与人工核对，**不参与运行逻辑**（运行时时代仍取 `FactionEra.ts` 的 `FACTION_ERA`）。
 *
 * 🔴 2026-11-10 主人令「给每个势力添加一个起始年代和结束年代的属性。都要是一个数字，可以估算出一个数，不能约」：
 *   · start / end 一律**必填数字**（不再允许 null）；史无确载者按通行说法估一个定数，估算依据写在 note；
 *   · 至今存续者 end 一律取 1900（按四时代年段终点「帝国＝1500–1900」截断，与 2026-11-04 审计 ONGOING_END=1900 同口径）；
 *   · panshu（叛军，游戏机制势力）按哨位取 -9999／9999，不作历史纪年，六类检查照旧不查它。
 *
 * 字段：
 *   · start / end：该势力作为独立政治实体（政权/王朝/城邦/部族/部落联盟/苏丹国/汗国）的存续起止年；
 *     公元前为负数；end 取被灭/被并入/改号之年（含该年）。
 *   · source：史书出处或百科条目（史无确载者注明「不确定」）。
 *   · note：补充说明；按估算取定数的，估算依据一律写在此处。
 *
 * 四时代年段（2026-11-03 终定）：古典＝起始–476｜封建＝476–1050｜城堡＝1050–1500｜帝国＝1500–1900（1900 后仍归帝国）。
 * 审计：scratch/audit_era_majority.mts（多数年段 vs FACTION_ERA 逐家比对）。
 */

export interface FactionSpan {
    /** 起始年（公元前为负数）；🔴 2026-11-10 主人令：一律必填数字，史无确载者按估算取定数（估算依据在 note） */
    start: number;
    /** 终止年（含该年）；至今存续者按游戏纪年终点 1900 截断 */
    end: number;
    /** 史书出处 / 百科条目；不确定者注明原因 */
    source: string;
    /** 补充说明（多段复国、朝代更替、估算依据等） */
    note?: string;
}

