    chengjia: { start: 23, end: 36, source: '《后汉书·公孙述传》：更始元年（23）公孙述据成都自称辅汉将军兼益州牧（25年称帝号成家），建武十二年（36）吴汉灭之｜确证；开国/起事将领年逾20岁（公孙述 生-15 登6，起事时38岁），按规则维持信史起兵/立国年23，建议百岁出场年取 max(登场年,势力起始年)', note: '2026-11-11 GG第五轮核定：原 25–36' },
    qianshu: { start: 887, end: 925, source: '《新五代史·前蜀世家》：光启三年（887）王建据阆州起兵经略两川（891入成都、907称帝），925年后唐灭前蜀｜确证；开国/起事将领年逾20岁（王建 生847 登867，起事时40岁），按规则维持信史起兵/立国年887，建议百岁出场年取 max(登场年,势力起始年)', note: '2026-11-11 GG第五轮核定：原 907–925' },
    chuguo: { start: -1030, end: -202, source: '《史记·楚世家》《项羽本纪》：约前1030年熊绎受封建楚，前223年秦灭楚后前208年项梁立楚怀王心复楚，前202年项羽败亡西楚终｜确证（前223、前202正史确载，熊绎受封约前1030年）', note: '2026-11-11 GG第五轮核定：原 -1030–-223' },
    liusong: { start: 404, end: 479, source: '《宋书·武帝纪》：404年刘裕于京口起兵讨平桓玄掌握东晋军政（420年代晋建宋），479年萧道成代宋｜确证；开国/起事将领年逾20岁（刘裕 生363 登383，起事时41岁），按规则维持信史起兵/立国年404，建议百岁出场年取 max(登场年,势力起始年)', note: '2026-11-11 GG第五轮核定：原 420–479' },
    nanqi: { start: 479, end: 502, source: '《南齐书》：479 年萧道成建齐，502 年萧衍代齐。' },
    yangwu: { start: 883, end: 937, source: '《新五代史·吴世家》：中和三年（883）杨行密据庐州起家（892领淮南节度使、902封吴王），937年徐知诰代吴｜确证；开国/起事将领年逾20岁（杨行密 生852 登872，起事时31岁），按规则维持信史起兵/立国年883，建议百岁出场年取 max(登场年,势力起始年)', note: '2026-11-11 GG第五轮核定：原 902–937' },
    nantang: { start: 931, end: 975, source: '《新五代史·南唐世家》：大和三年（931）徐知诰（李昪）出镇金陵专制吴政开齐国基业（937年代吴建唐），975年亡于宋｜确证；开国/起事将领年逾20岁（李昪 生889 登909，起事时42岁），按规则维持信史起兵/立国年931，建议百岁出场年取 max(登场年,势力起始年)', note: '2026-11-11 GG第五轮核定：原 937–975' },
    machu: { start: 896, end: 951, source: '《新五代史·楚世家》：乾宁三年（896）马殷据潭州领湖南留后开基（907封楚王），951年南唐灭马楚｜确证；开国/起事将领年逾20岁（马殷 生852 登872，起事时44岁），按规则维持信史起兵/立国年896，建议百岁出场年取 max(登场年,势力起始年)', note: '2026-11-11 GG第五轮核定：原 907–951' },
    nanhan: { start: 894, end: 971, source: '《新五代史·南汉世家》：乾宁元年（894）刘隐嗣父刘谦封州刺史旋掌清海军割据岭南（917刘龑称帝），971年亡于北宋｜确证', note: '2026-11-11 GG第五轮核定：原 917–971' },
    fangguozhen: { start: 1348, end: 1367, source: '《明史·方国珍传》：1348 年方国珍起兵据庆元，1367 年（吴元年）降于朱元璋。' },
    liang_shuofang: { start: 617, end: 621, source: '《旧唐书·萧铣传》：617 年萧铣据江陵称梁王（年号鸣凤），618 年称帝，621 年为李孝恭、李靖所灭（亡于江陵）。', note: '🔴 [2026-11-04 按历史修复] 原把萧铣与梁师都并作「大梁」（617–628），现拆为两家：本行只记萧铣（势力名「鸣凤」）。' },
    liangshidu: { start: 617, end: 628, source: '《旧唐书·梁师都传》：617 年梁师都据朔方（夏州）称梁帝、年号永隆，受突厥册封，628 年为堂弟梁洛仁所杀、举城降唐。', note: '🔴 [2026-11-04 按历史修复] 从原「大梁」拆出单立（势力名「永隆」，首府长泽，都统万城）。' },
    qianliang: { start: 301, end: 376, source: '《晋书·张轨传》：301年张轨任凉州刺史据河西保境开基（314张寔自用建兴年号），376年前秦灭前凉｜确证；开国/起事将领年逾20岁（张轨 生255 登275，起事时46岁），按规则维持信史起兵/立国年301，建议百岁出场年取 max(登场年,势力起始年)', note: '2026-11-11 GG第五轮核定：原 314–376' },
    liangzhou: { start: 185, end: 189, source: '《后汉书·董卓传》：185 年（中平二年）凉州北宫伯玉等起兵，王国继领其众，189 年王国败死后部众离散。', note: '不确定：王国割据的起止年份史载模糊。' },
    dangchang_guo: { start: 424, end: 566, source: '《魏书·宕昌传》：宕昌羌梁勤称王（约 424 年），566 年为北周所灭。' },
    sanada: { start: 1583, end: 1600, source: 'Wikipedia「真田氏」：1583 年真田昌幸据上田自立，1600 年关原后上田开城、昌幸被流。', note: '家名后以松代藩存续至明治。' },
    tokugawa: { start: 1471, end: 1868, source: 'Wikipedia「松平氏」「德川幕府」：1471年松平信光攻取三河安祥城确立安祥松平宗家（家康1566改姓德川、1603开幕），1868年大政奉还｜确证', note: '2026-11-11 GG第五轮核定：原 1603–1868' },
