    uesugi: { start: 1368, end: 1871, source: 'Wikipedia「上杉氏」「関東管領」「米沢藩」：1368 年上杉宪显复任关东管领确立上杉氏关东统治（扇谷、山内两上杉；1561 年上杉谦信入继山内上杉家督），1871 年米泽藩废藩置县。' },
    takeda: { start: 1521, end: 1582, source: 'Wikipedia「Takeda clan」：武田信虎 1521 年统一甲斐成战国大名，1582 年天目山之战灭亡。' },
    toyotomi: { start: 1573, end: 1615, source: 'Wikipedia「Toyotomi clan」：1573年秀吉受封近江长滨城主改姓羽柴创立羽柴（丰臣）政权家臣团（1585任关白），1615年大坂夏之阵灭亡｜确证；开国/起事将领年逾20岁（丰臣秀吉 生1537 登1557，起事时36岁），按规则维持信史起兵/立国年1573，建议百岁出场年取 max(登场年,势力起始年)', note: '2026-11-11 GG第五轮核定：原 1585–1615' },
    utsunomiya: { start: 1185, end: 1597, source: 'Wikipedia「Utsunomiya clan」：1597 年宇都宫氏被丰臣秀吉改易除封。', note: '不确定起始：镰仓以来为下野豪族，独立政权起点无定说。｜估算依据：镰仓以来世居下野宇都宫，取镰仓幕府立1185。' },
    nanchou: { start: 1287, end: 1392, source: 'Wikipedia「大覚寺統」「南北朝 (日本)」：1287年龟山上皇一系形成大觉寺统（1318后醍醐天皇即位、1331元弘之乱、1336吉野南朝），1392年南北朝合一｜确证', note: '2026-11-11 GG第五轮核定：原 1336–1392' },
    nanbu_shi: { start: 1191, end: 1871, source: 'Wikipedia「Nanbu clan」：盛冈藩至 1871 年废藩置县。', note: '不确定起始：镰仓期入陆奥，独立政权起点无定说。｜估算依据：镰仓期入陆奥，取南部光行受领糠部之1191（通行说法）。' },
    shoni: { start: 1189, end: 1551, source: 'Wikipedia「Shōni clan」：1551 年少弐冬尚为龙造寺隆信所灭。', note: '不确定起始：文治年间任镇西奉行，独立政权起点无定说。｜估算依据：文治年间（1189）武藤资頼任镇西奉行（通行说法）。' },
