    yalan: { start: -1200, end: -732, source: 'Wikipedia「Aram-Damascus」：约前 12 世纪立国，前 732 年为亚述提格拉特帕拉沙尔三世所灭（利汛被杀）。', note: '起点为约数。' },
    yaqi: { start: 1496, end: 1900, source: 'Wikipedia「Aceh Sultanate」：1496年阿里·穆加亚特沙建亚齐苏丹国，1903年降荷，按规则于1900截断｜确证', note: '2026-11-11 GG第五轮核定：原 1496–1903' },
    zhamolin: { start: 1124, end: 1766, source: 'Wikipedia「Calicut kingdom」：1124 年萨穆蒂里（扎莫林）建国，1766 年为迈索尔海达尔·阿里吞并。', note: '1792 年后复为英属附庸，1806 年王国告终。🔴 [2026-11-04 按历史修复] 势力名由「扎莫林」（统治者称号）改为政权名「卡利卡特」。' },
    jianwen: { start: 1398, end: 1402, source: '《明史·恭闵帝本纪》：洪武三十一年闰五月（1398）朱允炆即帝位（次年改元建文），1402年靖难燕军入京｜确证；开国/起事将领年逾20岁（铁铉 生1366 登1386，起事时32岁），按规则维持信史起兵/立国年1398，建议百岁出场年取 max(登场年,势力起始年)', note: '2026-11-11 GG第五轮核定：原 1399–1402' },
